import{_ as e}from"./chunks/me3.CrD21wG6.js";import{_ as i,o,c as t,ae as r}from"./chunks/framework.D_sy9b7Z.js";const f=JSON.parse('{"title":"Fabio Di Nocera","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),l={name:"index.md"};function n(c,a,s,d,m,p){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="fabio-di-nocera" tabindex="-1">Fabio Di Nocera <a class="header-anchor" href="#fabio-di-nocera" aria-label="Permalink to &quot;Fabio Di Nocera&quot;">​</a></h1><br><br><img src="'+e+'" alt="Foto profilo" class="foto-piccola"><h2 id="una-breve-bio" tabindex="-1">Una breve bio <a class="header-anchor" href="#una-breve-bio" aria-label="Permalink to &quot;Una breve bio&quot;">​</a></h2><p>Nato a <a href="https://it.wikipedia.org/wiki/Panuozzo" target="_blank" rel="noreferrer">Gragnano</a> nel lontano 1992, cresciuto a Castellammare di Stabia, ho studiato Fisica all&#39;Università degli Studi di Napoli &quot;Federico II&quot;, dove ho conseguito sia la laurea triennale che quella magistrale.</p><p>Durante i miei studi, mi sono avvicinato al mondo dei <em>metodi matematici per la fisica</em>, in particolare alle applicazioni della geometria differenziale nel campo della meccanica quantistica e della teoria dell&#39;informazione. Questo percorso mi ha portato poi ad una breve ma felice esperienza nella ricerca, come dottorando al Max Planck Institut per la matematica nelle scienze di Lipsia. Trovate le mie pubblicazioni nella <a href="./ricerca.html">pagina</a> di questo sito dedicata al mio lavoro scientifico.</p><p>Un ottimo uso di questo spazio è ringraziare ancora una volta i professori Patrizia Vitale, Giuseppe Marmo e Jürgen Jost per la supervisione illuminante e premurosa.</p><p>Insegno e parlo di matematica e di scienze (tediando i più) da diversi anni ormai, ma è da quando ho difeso la mia tesi di dottorato, nell&#39;aprile del 2024, che ho deciso di dedicarmi professionalmente sia alla didattica che alla comunicazione della matematica e delle scienze.</p><h2 id="cosa-c-e-su-questo-sito" tabindex="-1">Cosa c&#39;è su questo sito? <a class="header-anchor" href="#cosa-c-e-su-questo-sito" aria-label="Permalink to &quot;Cosa c&#39;è su questo sito?&quot;">​</a></h2><p>Un po&#39; di cose diverse.</p><p>La pagina <a href="./ricerca.html">ricerca</a> potete serenamente saltarla, lì ci sono i prodotto del mio lavoro scientifico (articoli, conferenze, tesi), negli anni 2020-2024.</p><p>Nella pagina <a href="./didattica.html">didattica</a> troverete delle <em>pagine tematiche</em> dedicate a vari argomenti di matematica e di fisica, con l&#39;idea di spiegarli sfruttando la possibilità di creare modelli esplorabili, animazioni e grafici interattivi.</p><p>Nella pagina <a href="./comunicazione.html">comunicazione</a> ci sono invece degli articoli che rappresentano un tentativo (forse maldestro) di tenere insieme cose diverse: divulgazione e giornalismo scientifici in senso stretto, ma anche aspetti più <em>laterali</em>, come escursioni nella storia della scienza o della tecnica, o discussioni sul modo in cui percepiamo la scienza e la matematica, il modo in cui ne parliamo e il modo in cui la insegniamo.</p><h2 id="contatti-e-link" tabindex="-1">Contatti e link <a class="header-anchor" href="#contatti-e-link" aria-label="Permalink to &quot;Contatti e link&quot;">​</a></h2><ul><li><strong>Email:</strong> <a href="mailto:fabiodncr@gmail.com" target="_blank" rel="noreferrer">fabiodncr@gmail.com</a></li><li><a href="https://github.com/Fabiodncr" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://www.linkedin.com/in/fabio-di-nocera-647123180" target="_blank" rel="noreferrer">Linkedin</a></li><li><a href="https://scholar.google.com/citations?view_op=list_works&amp;hl=it&amp;user=f4tI0xcAAAAJ" target="_blank" rel="noreferrer">Google Scholar</a></li></ul>',16)])])}const b=i(l,[["render",n]]);export{f as __pageData,b as default};
